g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "tool-replacement-matrix",
  "x": 72, "y": 184, "width": 1136, "height": 400,
  "header_rows": 1,
  "column_widths": [240, 460, 436],
  "row_heights": [52, 58, 58, 58, 58, 58, 58],
  "style": {
    "font_family": "Microsoft YaHei",
    "font_size": 24,
    "header_font_size": 18,
    "band_row": false,
    "header_fill": "#1E2A3D",
    "header_text": "#9BA9BC",
    "body_fill": "#0B1220",
    "body_text": "#E6EDF3",
    "border_color": "#243349",
    "border_width": 1
  },
  "defaults": {
    "cell": {
      "valign": "middle",
      "padding": {"left": 24, "right": 24, "top": 6, "bottom": 6},
      "borders": {
        "left": {"style": "none"},
        "right": {"style": "none"},
        "top": {"style": "solid", "color": "#243349", "width": 1},
        "bottom": {"style": "solid", "color": "#243349", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "任务", "align": "l"},
    {"text": "传统命令", "align": "l"},
    {"text": "uv 命令", "align": "l", "fill": "#FF8A3D", "color": "#0B1220", "bold": true}
  ],
  "rows": [
    [
      {"text": "建虚拟环境", "fill": "#101929", "color": "#E6EDF3"},
      {"fill": "#0B1220", "paragraphs": [{"align": "l", "runs": [{"text": "python -m venv .venv", "font_family": "Consolas", "font_size": 20, "color": "#9BA9BC"}]}]},
      {"fill": "#131C2E", "paragraphs": [{"align": "l", "runs": [{"text": "uv venv", "font_family": "Consolas", "font_size": 20, "color": "#E6EDF3"}]}]}
    ],
    [
      {"text": "装包", "fill": "#101929", "color": "#E6EDF3"},
      {"fill": "#0B1220", "paragraphs": [{"align": "l", "runs": [{"text": "pip install requests", "font_family": "Consolas", "font_size": 20, "color": "#9BA9BC"}]}]},
      {"fill": "#131C2E", "paragraphs": [{"align": "l", "runs": [{"text": "uv pip install requests", "font_family": "Consolas", "font_size": 20, "color": "#E6EDF3"}]}]}
    ],
    [
      {"text": "锁定依赖", "fill": "#101929", "color": "#E6EDF3"},
      {"fill": "#0B1220", "paragraphs": [{"align": "l", "runs": [{"text": "pip-compile requirements.in", "font_family": "Consolas", "font_size": 20, "color": "#9BA9BC"}]}]},
      {"fill": "#131C2E", "paragraphs": [{"align": "l", "runs": [{"text": "uv pip compile requirements.in", "font_family": "Consolas", "font_size": 20, "color": "#E6EDF3"}]}]}
    ],
    [
      {"text": "同步环境", "fill": "#101929", "color": "#E6EDF3"},
      {"fill": "#0B1220", "paragraphs": [{"align": "l", "runs": [{"text": "pip-sync requirements.txt", "font_family": "Consolas", "font_size": 20, "color": "#9BA9BC"}]}]},
      {"fill": "#131C2E", "paragraphs": [{"align": "l", "runs": [{"text": "uv pip sync requirements.txt", "font_family": "Consolas", "font_size": 20, "color": "#E6EDF3"}]}]}
    ],
    [
      {"text": "跑命令行工具", "fill": "#101929", "color": "#E6EDF3"},
      {"fill": "#0B1220", "paragraphs": [{"align": "l", "runs": [{"text": "pipx run ruff", "font_family": "Consolas", "font_size": 20, "color": "#9BA9BC"}]}]},
      {"fill": "#131C2E", "paragraphs": [{"align": "l", "runs": [{"text": "uvx ruff", "font_family": "Consolas", "font_size": 20, "color": "#E6EDF3"}]}]}
    ],
    [
      {"text": "装 Python 版本", "fill": "#101929", "color": "#E6EDF3"},
      {"fill": "#0B1220", "paragraphs": [{"align": "l", "runs": [{"text": "pyenv install 3.12", "font_family": "Consolas", "font_size": 20, "color": "#9BA9BC"}]}]},
      {"fill": "#131C2E", "paragraphs": [{"align": "l", "runs": [{"text": "uv python install 3.12", "font_family": "Consolas", "font_size": 20, "color": "#E6EDF3"}]}]}
    ]
  ]
}
